-- CMS inline localized blocks (en + pt-BR per text field)

ALTER TABLE public.cms_pages
  ALTER COLUMN title TYPE jsonb
  USING jsonb_build_object(
    'en', COALESCE(title, ''),
    'pt-BR', ''
  );

UPDATE public.cms_pages
SET
  title = '{"en":"Leading Sires Registry","pt-BR":"Leading Sires Registry"}'::jsonb,
  blocks = '[{"type":"landing_hero","imageSrc":"/splash_page.png","overline":{"en":"NOW ONBOARDING FOUNDING STALLIONS","pt-BR":"ACEITANDO GARANHÕES FUNDADORES"},"titleBeforeAccent":{"en":"Performance Stallion Breeding","pt-BR":"Registro de Garanhões de Performance"},"titleAccent":{"en":"Registry","pt-BR":""},"subtitle":{"en":"Pedigree · Performance · Breeding Information","pt-BR":"Pedigree · Performance · Informações de Reprodução"},"description":{"en":"Leading Sires is a performance-focused sire registry created for breeders and horsemen who value proven working genetics.","pt-BR":"Leading Sires é um registro de garanhões focado em performance, criado para criadores e profissionais que valorizam genética de trabalho comprovada."},"tags":[{"en":"Quarter Horses","pt-BR":"Quarter Horses"},{"en":"Paints","pt-BR":"Paints"},{"en":"Appaloosas","pt-BR":"Appaloosas"}],"cta":{"label":{"en":"Stallion Directory","pt-BR":"Diretório de Garanhões"},"href":"/stallions"},"referenceLeftTitle":{"en":"Performance Stallion Breeding Registry","pt-BR":"Registro de Garanhões de Performance"},"referenceLeftText":{"en":"Each stallion is presented on a single reference page that consolidates pedigree, performance and breeding information, supported by official association records and ranch or farm websites.","pt-BR":"Cada garanhão é apresentado em uma única página de referência que consolida pedigree, performance e informações de reprodução, com suporte de registros oficiais de associações e sites de haras ou fazendas."},"referenceRightTitle":{"en":"Independent Reference","pt-BR":"Referência Independente"},"referenceRightText":{"en":"Leading Sires is an independent reference platform, not a marketplace. We exist to provide clear and accessible information for breeders and horsemen across international borders.","pt-BR":"Leading Sires é uma plataforma de referência independente, não um marketplace. Existimos para fornecer informações claras e acessíveis para criadores e profissionais em diferentes países."},"industryTitle":{"en":"Built for the Western Performance Industry","pt-BR":"Construído para a Indústria de Performance Western"},"industryText":{"en":"By centralizing verifiable data, we reduce administrative burden and contribute to industry sustainability. Our registry supports owners and farms across:","pt-BR":"Ao centralizar dados verificáveis, reduzimos a carga administrativa e contribuímos para a sustentabilidade do setor. Nosso registro apoia proprietários e haras em:"},"regions":[{"en":"Australia","pt-BR":"Austrália"},{"en":"New Zealand","pt-BR":"Nova Zelândia"},{"en":"Europe","pt-BR":"Europa"},{"en":"Canada","pt-BR":"Canadá"},{"en":"North America","pt-BR":"América do Norte"},{"en":"South America","pt-BR":"América do Sul"}],"stats":[{"value":{"en":"6+","pt-BR":"6+"},"label":{"en":"Regions Covered","pt-BR":"Regiões Cobertas"}},{"value":{"en":"1","pt-BR":"1"},"label":{"en":"Centralised Registry","pt-BR":"Registro Centralizado"}},{"value":{"en":"3","pt-BR":"3"},"label":{"en":"Breeds","pt-BR":"Raças"}},{"value":{"en":"Free","pt-BR":"Grátis"},"label":{"en":"Public Access","pt-BR":"Acesso Público"}}],"learnMore":{"label":{"en":"Learn More About The Registry","pt-BR":"Saiba Mais Sobre o Registro"},"href":"/about"},"readyTitle":{"en":"Ready to list your stallion?","pt-BR":"Pronto para listar seu garanhão?"},"readySubtitle":{"en":"Join the founding registry","pt-BR":"Junte-se ao registro fundador"},"readyCta":{"label":{"en":"Submit a Listing","pt-BR":"Enviar um Anúncio"},"href":"/submit-stallion/before-submit"}}]'::jsonb,
  updated_at = now()
WHERE slug = 'landing';

UPDATE public.cms_pages
SET
  title = '{"en":"About us","pt-BR":"Sobre nós"}'::jsonb,
  blocks = '[{"type":"heading","level":1,"text":{"en":"About the Leading Sires Registry","pt-BR":"Sobre o Leading Sires Registry"},"align":"center"},{"type":"text","align":"center","text":{"en":"Leading Sires Registry is an independent, performance-focused reference created for breeders and horsemen who value proven working genetics over marketing, built to function across international borders.\n\nThe registry provides a single, seasonally updated reference page per stallion, consolidating publicly available performance, pedigree, and breeding information, alongside stud-provided details. Each listing links directly back to the official breed association and the stallion''s home stud or ranch, ensuring the information remains transparent and verifiable.\n\nLeading Sires is not a stud book, association or marketplace. It does not replace any existing breed or discipline registers. Instead, it exists to reduce administrative burden for stallion owners, provide clear and accessible information for breeders, and contribute positively to the sustainability and transparency of the western performance horse industry.","pt-BR":"O Leading Sires Registry é uma referência independente e focada em performance, criada para criadores e profissionais que valorizam genética de trabalho comprovada acima de marketing, projetada para funcionar além das fronteiras internacionais.\n\nO registro oferece uma única página de referência atualizada sazonalmente por garanhão, consolidando informações públicas de performance, pedigree e reprodução, junto com detalhes fornecidos pelo haras. Cada anúncio vincula diretamente à associação oficial da raça e ao haras ou fazenda do garanhão, garantindo que as informações permaneçam transparentes e verificáveis.\n\nLeading Sires não é um stud book, associação ou marketplace. Não substitui registros existentes de raça ou disciplina. Em vez disso, existe para reduzir a carga administrativa dos proprietários de garanhões, fornecer informações claras e acessíveis para criadores e contribuir positivamente para a sustentabilidade e transparência da indústria de cavalos de performance western."}},{"type":"grid","columns":2,"cells":[[{"type":"heading","level":2,"text":{"en":"Pedigree and Historical Records","pt-BR":"Pedigree e Registros Históricos"}},{"type":"text","text":{"en":"The registry preserves pedigree and lineage information for stallions regardless of current standing status. Deceased stallions and historically significant sires may be included for pedigree reference and research purposes.\n\nWhere a stallion is no longer standing or ownership information is incomplete, records are presented in a factual, non-speculative manner.","pt-BR":"O registro preserva informações de pedigree e linhagem de garanhões independentemente do status atual de reprodução. Garanhões falecidos e garanhões historicamente significativos podem ser incluídos para referência de pedigree e fins de pesquisa.\n\nQuando um garanhão não está mais em reprodução ou as informações de propriedade estão incompletas, os registros são apresentados de forma factual, sem especulação."}}],[{"type":"heading","level":2,"text":{"en":"International Scope","pt-BR":"Escopo Internacional"}},{"type":"text","text":{"en":"The Leading Sires Registry support owners and farms across Australia, New Zealand, Canada, North and South America and Europe.\n\nListings are presented in a consistent, non-commercial format and link back to official association records and stud or distributor websites in their original language, allowing breeders to access reliable information across jurisdictions.","pt-BR":"O Leading Sires Registry apoia proprietários e haras na Austrália, Nova Zelândia, Canadá, América do Norte e do Sul e Europa.\n\nOs anúncios são apresentados em formato consistente e não comercial e vinculam aos registros oficiais de associações e sites de haras ou distribuidores em seu idioma original, permitindo que criadores acessem informações confiáveis em diferentes jurisdições."}}],[{"type":"heading","level":2,"text":{"en":"Independence of the Registry","pt-BR":"Independência do Registro"}},{"type":"text","text":{"en":"Inclusion of an owner or stallion profile does not imply endorsement, recommendation, or commercial partnership. The Leading Sires Registry functions as an independent reference platform, not a marketing service.","pt-BR":"A inclusão de um proprietário ou perfil de garanhão não implica endosso, recomendação ou parceria comercial. O Leading Sires Registry funciona como uma plataforma de referência independente, não um serviço de marketing."}}],[{"type":"heading","level":2,"text":{"en":"Updates and Changes","pt-BR":"Atualizações e Alterações"}},{"type":"text","text":{"en":"Ownership, standing status, and service arrangements may change over time. Where possible, historical changes are recorded to maintain the integrity of the registry.\n\nOwners and authorised representatives are encouraged to keep information current for active records.","pt-BR":"Propriedade, status de reprodução e arranjos de serviço podem mudar ao longo do tempo. Sempre que possível, alterações históricas são registradas para manter a integridade do registro.\n\nProprietários e representantes autorizados são incentivados a manter as informações atualizadas para registros ativos."}}]]},{"type":"buttons","align":"center","items":[{"label":{"en":"Stallion Directory","pt-BR":"Diretório de Garanhões"},"href":"/stallions","variant":"secondary"},{"label":{"en":"Submit a Stallion Listing","pt-BR":"Enviar um Anúncio de Garanhão"},"href":"/submit-stallion/before-submit","variant":"secondary"}]}]'::jsonb,
  updated_at = now()
WHERE slug = 'about';

UPDATE public.cms_pages
SET
  title = '{"en":"Pricing","pt-BR":"Preços"}'::jsonb,
  blocks = '[{"type":"heading","level":1,"text":{"en":"Pricing","pt-BR":"Preços"},"align":"center"},{"type":"text","align":"center","text":{"en":"The Leading Sires Registry is an independent global reference, not a marketplace. Listings are presented in a consistent, non commercial format and are not ranked, promoted, or prioritised.","pt-BR":"O Leading Sires Registry é uma referência global independente, não um marketplace. Os anúncios são apresentados em formato consistente e não comercial e não são classificados, promovidos ou priorizados."}},{"type":"heading","level":2,"text":{"en":"Stallion Listings","pt-BR":"Anúncios de Garanhões"},"pricingCard":true},{"type":"text","text":{"en":"Farm/Ranch Registry Account – 79 per year\n\n(USD/EUR/AUD/CAD/NZD – billed in your selected country)\n\n• Unlimited stallion profiles under one farm or ranch\n• Standardised stallion pages with verified registry links\n• Genetics, breeding information, media and service provider links\n• Updates managed annually or as required\n• No advertising, no featured placements, no performance rankings","pt-BR":"Conta de Registro de Fazenda/Haras – 79 por ano\n\n(USD/EUR/AUD/CAD/NZD – cobrado no país selecionado)\n\n• Perfis ilimitados de garanhões sob uma fazenda ou haras\n• Páginas padronizadas de garanhões com links de registro verificados\n• Genética, informações de reprodução, mídia e links de provedores de serviço\n• Atualizações gerenciadas anualmente ou conforme necessário\n• Sem publicidade, sem destaques pagos, sem rankings de performance"}},{"type":"heading","level":2,"text":{"en":"Pedigree-Only & Historical Listings","pt-BR":"Anúncios Apenas de Pedigree e Históricos"}},{"type":"text","text":{"en":"Pedigree and lineage records may be included at no cost where a stallion is:\n\n• deceased\n• no longer standing\n• of historical or breeding significance only\n\nThese records are presented for reference and research purposes and do not imply current availability or commercial activity.","pt-BR":"Registros de pedigree e linhagem podem ser incluídos sem custo quando um garanhão está:\n\n• falecido\n• fora de reprodução\n• apenas de significância histórica ou reprodutiva\n\nEsses registros são apresentados para fins de referência e pesquisa e não implicam disponibilidade atual ou atividade comercial."}},{"type":"heading","level":2,"text":{"en":"International Listings & Currency","pt-BR":"Anúncios Internacionais e Moeda"}},{"type":"text","text":{"en":"The Leading Sires Registry supports listings across:\n\n• Australia\n• New Zealand\n• Canada\n• North & South America\n• Europe","pt-BR":"O Leading Sires Registry suporta anúncios em:\n\n• Austrália\n• Nova Zelândia\n• Canadá\n• América do Norte e do Sul\n• Europa"}},{"type":"heading","level":2,"text":{"en":"Important Notes","pt-BR":"Notas Importantes"}},{"type":"text","text":{"en":"• The Leading Sires Registry is not a stud book, association or marketplace.\n• Listings are factual and reference based.","pt-BR":"• O Leading Sires Registry não é um stud book, associação ou marketplace.\n• Os anúncios são factuais e baseados em referência."}}]'::jsonb,
  updated_at = now()
WHERE slug = 'pricing';
